        for c in range(cols):
            if grid[r][c] != background:
                colors.add(grid[r][c])

    output = [row[:] for row in grid]

    # 4-connectivity: up, down, left, right
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    for color in colors:
        cells = [(r, c) for r in range(rows) for c in range(cols) if grid[r][c] == color]
        if not cells:
            continue

        visited = set()
        for start_node in cells:
            if start_node in visited:
                continue

            component = []
            queue = [start_node]
            visited.add(start_node)

            while queue:
                r, c = queue.pop(0)
                component.append((r, c))
                for dr, dc in dirs:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols:
                        if grid[nr][nc] == color and (nr, nc) not in visited:
                            visited.add((nr, nc))
                            queue.append((nr, nc))

            min_r, max_r = rows, -1
            min_c, max_c = cols, -1
            for r, c in component:
                min_r = min(min_r, r)
                max_r = max(max_r, r)
                min_c = min(min_c, c)
                max_c = max(max_c, c)

            width = max_c - min_c + 1
            height = max_r - min_r + 1
            area = width * height

            if area == 0:
                continue

